window.ScripturaLexicons.BDAG_PART_0183 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-01\" data-source=\"BDAG\" data-search=\"καίπερ conjunção embora; ainda que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καίπερ</td><td>conjunção</td><td>embora; ainda que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-02\" data-source=\"BDAG\" data-search=\"καιρός, οῦ, ὁ substantivo masculino tempo; ocasião; época BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καιρός, οῦ, ὁ</td><td>substantivo masculino</td><td>tempo; ocasião; época</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-03\" data-source=\"BDAG\" data-search=\"Καῖσαρ, αρος, ὁ nome próprio masculino; título imperial César; imperador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καῖσαρ, αρος, ὁ</td><td>nome próprio masculino; título imperial</td><td>César; imperador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-04\" data-source=\"BDAG\" data-search=\"Καισάρεια, ας, ἡ topônimo feminino Cesareia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καισάρεια, ας, ἡ</td><td>topônimo feminino</td><td>Cesareia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-05\" data-source=\"BDAG\" data-search=\"καίτοι, καίτοιγε conjunção; remissão veja καί 2iδ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καίτοι, καίτοιγε</td><td>conjunção; remissão</td><td>veja καί 2iδ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-06\" data-source=\"BDAG\" data-search=\"καίω verbo acender; arder; queimar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καίω</td><td>verbo</td><td>acender; arder; queimar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-07\" data-source=\"BDAG\" data-search=\"κἀκεῖ advérbio e ali; também ali BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀκεῖ</td><td>advérbio</td><td>e ali; também ali</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-08\" data-source=\"BDAG\" data-search=\"κἀκεῖθεν advérbio e dali; e então BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀκεῖθεν</td><td>advérbio</td><td>e dali; e então</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-09\" data-source=\"BDAG\" data-search=\"κἀκεῖνος, η, ο pronome contraído e aquele; também ele BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀκεῖνος, η, ο</td><td>pronome contraído</td><td>e aquele; também ele</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-10\" data-source=\"BDAG\" data-search=\"κἀκεῖσε advérbio e lá; e para lá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀκεῖσε</td><td>advérbio</td><td>e lá; e para lá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-11\" data-source=\"BDAG\" data-search=\"κακία, ας, ἡ substantivo feminino maldade; malícia; aflição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακία, ας, ἡ</td><td>substantivo feminino</td><td>maldade; malícia; aflição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-12\" data-source=\"BDAG\" data-search=\"κακοδιδασκαλέω verbo ensinar o mal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοδιδασκαλέω</td><td>verbo</td><td>ensinar o mal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-13\" data-source=\"BDAG\" data-search=\"κακοδιδασκαλία, ας, ἡ substantivo feminino ensino mau; doutrina falsa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοδιδασκαλία, ας, ἡ</td><td>substantivo feminino</td><td>ensino mau; doutrina falsa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-14\" data-source=\"BDAG\" data-search=\"κακοήθεια, ας, ἡ substantivo feminino malícia; malignidade; astúcia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοήθεια, ας, ἡ</td><td>substantivo feminino</td><td>malícia; malignidade; astúcia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-15\" data-source=\"BDAG\" data-search=\"κακοήθης, ες adjetivo malicioso; rancoroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοήθης, ες</td><td>adjetivo</td><td>malicioso; rancoroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-16\" data-source=\"BDAG\" data-search=\"κακολάλος remissão lexical veja κατάλαλος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακολάλος</td><td>remissão lexical</td><td>veja κατάλαλος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-17\" data-source=\"BDAG\" data-search=\"κακολογέω verbo difamar; injuriar; insultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακολογέω</td><td>verbo</td><td>difamar; injuriar; insultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-18\" data-source=\"BDAG\" data-search=\"κακοπάθεια remissão lexical veja κακοπαθία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοπάθεια</td><td>remissão lexical</td><td>veja κακοπαθία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-19\" data-source=\"BDAG\" data-search=\"κακοπαθέω verbo sofrer infortúnios; suportar dificuldades BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοπαθέω</td><td>verbo</td><td>sofrer infortúnios; suportar dificuldades</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0183-20\" data-source=\"BDAG\" data-search=\"κακοπαθία, ας, ἡ substantivo feminino sofrimento; infortúnio; perseverança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κακοπαθία, ας, ἡ</td><td>substantivo feminino</td><td>sofrimento; infortúnio; perseverança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0183-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καίπερ</h1><div class=\"entry-meta\"><span>conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">conjunção (documentada desde Od. 7, 224; SIG 709, 18; 1108, 8; PGiss 47, 22; PSI 298, 17; LXX, TestJos, Joseph., Just.) embora; normalmente construída com particípio (assim habitualmente; também em Diod S 8, 9, 2; 10, 19, 2; 17, 114, 1; Wsd 11:9; Jos., Ant. 1, 319; 3, 280; TestJos 10:5; com verbo em forma finita Just., A I, 4, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:8</a>; 7:5; 12:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:12</a>. Também 1 Cl 7:7; 16:2; ISm 3:3; MPol 17:1; Hv 3, 2, 9; Hs 8, 6, 4; 8, 11, 1 (B-D-F §425, 1; Rob. 1129; FScheidweiler, <span class=\"greek\">καίπερ</span> [título bibliográfico:] nebst e. Exkurs zum Hb: Her 83, ’55, 220–30).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καιρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(atestada desde Hesíodo; empréstimo lexical na literatura rabínica)\n ① um ponto ou período no tempo, tempo, período, frequentemente com a implicação de ser especialmente apropriado para alguma coisa, sem ênfase na cronologia exata\n ⓐ em sentido geral (cf. Just., D. 32, 4 <span class=\"greek\">τὸν γὰρ καιρὸν</span> [Da 7:26] <span class=\"greek\">ἑκατὸν ἔτη ἐξηγεῖσθε λέγεσθαι</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">δεκτός</span> tempo favorável <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:2a</a> (Is 49:8); cf. versículo 2b. <span class=\"greek\">καιροὶ χαλεποί</span> tempos difíceis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:1</a>. Com referência a tempos de crise para o Estado <span class=\"greek\">λοιμικοῦ καιροῦ</span> 1 Cl 55:1 (veja JFischer, nota ao trecho 322) <span class=\"greek\">καιροὶ καρποφόροι</span> tempos ou estações frutíferas (assim Achmes 156, 15f: <span class=\"greek\">καρποφόρος</span> é o <span class=\"greek\">καιρός</span> em que a árvore produz fruto, em contraste com o fim do outono, quando já não há produção) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a> (OLagercrantz, ZNW 31, ’32, 86s., propõe, com base no grego moderno, o significado de «condições meteorológicas», mas o plural depõe contra essa acepção). <span class=\"greek\">καιροὶ ἐαρινοί</span> 1 Cl 20:9.—<span class=\"greek\">ἔσται καιρὸς ὅτε</span> virá um tempo em que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:3</a>; <span class=\"greek\">εἰς τίνα ἢ ποῖον κ</span>. a que tempo ou a que espécie de tempo (alguns, por exemplo, a NRSV, interpretam <span class=\"greek\">τίνα</span>=a pessoa; cf., porém, PTebt 25, 18 [117 b.c.] <span class=\"greek\">καὶ διὰ τίνος καὶ ἀπὸ ποίου ἐπιδείγματος</span>; veja <span class=\"greek\">ποῖος</span> 1a<span class=\"greek\">α</span>, também <span class=\"greek\">ποτατός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a>. <span class=\"greek\">ἄχρι καιροῦ</span> até outra ocasião; por algum tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>; <span class=\"greek\">ἐν καιρῷ ὀλίγῳ</span> dentro de pouco tempo 1 Cl 23:4; <span class=\"greek\">ἐν παντὶ κ</span>. em todo tempo; sempre (Aristot. 117a, 35; Sir 26:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:18</a>; Hm 5, 2, 3. <span class=\"greek\">κατὰ καιρόν</span> de tempos em tempos; regularmente (TestJob 36:4; Lucian, Hermot. 10; Plut., Mor. 984d) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a> (veja também a acepção 2); 1 Cl 24:2; GJs 3:3; <span class=\"greek\">πρὸς κ</span>. por tempo limitado (talvez também «por ora»; cf. Strabo 6, 2, 3; Ps.-Plut., Fluv. 23; BGU 265, 20 [II a.d.]; 618, 19; 780, 14; Wsd 4:4; Philo, Post. Cai. 121; Jos., Bell. 6, 190; Tat. 13, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>. <span class=\"greek\">πρὸς καιρὸν ὥρας</span> (combinação de <span class=\"greek\">πρὸς κ</span>. e <span class=\"greek\">πρὸς ὥραν</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:5</a>; Phlm 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:35</a>]) por breve tempo (cf. a expressão «por um breve espaço de tempo») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>.\n ⓑ momento ou período especialmente apropriado: o tempo certo, oportuno, favorável <span class=\"greek\">ἐν καιρῷ</span> no tempo certo (X., An. 3, 1, 39; Diod S 36, 7, 2; Appian, Bell. Civ. 3, 8 §29; SIG 1268 [Praecepta Delphica II, 6; III b.c.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a> (cf., para ambas as passagens, Ps 103:27, com variante de leitura). <span class=\"greek\">καιρῷ</span> (Thu. 4, 59, 3 variante de leitura; Diog. L. 1, 41) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:10</a> (variante de leitura <span class=\"greek\">ἐν κ</span>.). <span class=\"greek\">τῷ καιρῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:2</a>. <span class=\"greek\">ὁ καιρὸς ὁ ἐμός</span>, <span class=\"greek\">ὁ καιρὸς ὁ ὑμέτερος</span> o tempo próprio para mim (para vós) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:6</a>, 8 (Eunápio, Vi. Iambl. p. 459 Didot: aquele que realiza milagres age <span class=\"greek\">ὅταν καιρὸς ᾖ</span>). <span class=\"greek\">νῦν κ</span>. <span class=\"greek\">ταῦτα ὑμᾶς μαθεῖν οὐκ ἔστιν</span> agora não é a ocasião para aprenderdes isso AcPl Ha 1, 26 (Just., D. 8, 1 <span class=\"greek\">ἃ νῦν κ</span>. <span class=\"greek\">οὐκ ἔστι λέγειν</span> e outros).—<span class=\"greek\">καιρὸν λαβεῖν</span> encontrar ocasião favorável; aproveitar a oportunidade (Lysias, C. Agor. 6; Cleanthes [III b.c.]: Stoic. I nº 573; Diod S 2, 6, 5; EpArist 248; Jos., Bell. 1, 527, Ant. 4, 10; cf. PTebt 332, 9). <span class=\"greek\">καιρὸν μεταλαβεῖν</span> (veja <span class=\"greek\">μεταλαμβάνω</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:25</a>. <span class=\"greek\">λαβεῖν κ</span>. <span class=\"greek\">εὔθετον</span> encontrar uma oportunidade conveniente Pol 13:1. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> ter oportunidade (Thu. 1, 42, 3; Pla., Ep. 7, 324b; Plut., Lucull. 501 [16, 4]; PFlor 259, 3; 1 Macc 15:34; Jos., Ant. 16, 73; 335; Ath., R. 23 p. 77, 6; Did., Gen. 112, 10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:15</a>; 2 Cl 16:1; ISm 9:1; IRo 2:1. <span class=\"greek\">ὀλίγον καιρὸν ἔχειν</span>, «ter pouco tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>. <span class=\"greek\">ἐξαγοράζεσθαι τὸν κ</span>. aproveitar ao máximo a oportunidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:16</a> (veja <span class=\"greek\">ἐξαγοράζω</span> 2). Sobre a variante de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:11</a>, veja <span class=\"greek\">δουλεύω</span> 2a<span class=\"greek\">β</span> e b. <span class=\"greek\">κατὰ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:6</a> liga-se mais naturalmente a <span class=\"greek\">ἀπέθανεν</span> do que a <span class=\"greek\">ἀσεβῶν</span> (cf. <span class=\"greek\">κατὰ καιρὸν θεριζόμενος</span>, «colhido no tempo próprio» Job 5:26).—O conceito de tempo oportuno frequentemente se funde ao de\n ② um período determinado para um acontecimento: tempo definido, fixado. Em uso absoluto, <span class=\"greek\">καιροί</span> designa épocas festivas (Ex 23:14, 17; Lev 23:4.—Talvez também ao lado de <span class=\"greek\">θυσίαι</span> na inscrição de Sinuri, edição de LRobert ’45 no. 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:10</a> (<span class=\"greek\">κ</span>. com <span class=\"greek\">ἡμέρα</span>, como em Polyaenus 8, 23, 17). <span class=\"greek\">τὰς τῶν καιρῶν ἀλλαγὰς καταδιαιρεῖν</span> … <span class=\"greek\">ἃ μὲν εἰς ἑορτάς</span>, <span class=\"greek\">ἃς δὲ εἰς πένθη</span> estabelecer períodos de jejum e luto segundo a alternância das estações Dg 4:5.—Não raramente acompanha um genitivo, que indica a razão pela qual o tempo é reservado (Pla., Leg. 4, 709c <span class=\"greek\">χειμῶνος καιρός</span>; Aesop, Fab. 258 P.=255 H-H.//206 Ch. <span class=\"greek\">ἀπολογίας κ</span>., também frequentemente na LXX; Philo, Spec. Leg. 1, 191 <span class=\"greek\">κ</span>. <span class=\"greek\">εὐφροσύνης</span>; Jos., Ant. 18, 74; Tat. 36, 1 <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκεῖνον αὐτὸν</span> … <span class=\"greek\">τὸν τοῦ πολέμου κ</span>.; Hippol., Ref. 9, 30, 27 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς παρουσίας</span>; Did., Gen. 175, 2 <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ ἐξελθεῖν εἰς τὴν γῆν</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">θερισμοῦ</span> tempo da colheita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:30</a> (JosAs 2:19). <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν καρπῶν</span> tempo em que os frutos amadurecem 21:34; cf. versículo 41. <span class=\"greek\">κ</span>. <span class=\"greek\">σύκων</span> tempo em que os figos amadurecem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:13</a> (ParJer 5:31; cf. Horapollo 2, 92 <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τῶν ἀμπέλων</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">μετανοίας</span> tempo de arrependimento 2 Cl 8:2. <span class=\"greek\">κ</span>. <span class=\"greek\">πειρασμοῦ</span>, «tempo de provação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:13b</a>. <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τῆς ἀναλύσεως</span> o tempo da morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:6</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπισκοπῆς σου</span>, «tempo de tua visitação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:44</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">διορθώσεως</span>, «tempo de reforma», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἡλικίας</span>, «tempo de idade adequada», 11:11. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς ἡγεμονίας Ποντίου Πιλάτου</span> o período do governo de Pôncio Pilatos IMg 11. <span class=\"greek\">κατὰ τὸν καιρὸν τοῦ μαρτυρίου</span> por ocasião do martírio EpilMosq 2 (cf. Mel., HE 4, 26, 3 <span class=\"greek\">ᾧ Σάγαρις καιρῷ ἐμαρτύρησεν</span>). <span class=\"greek\">ἐν τῷ ἑαυτοῦ καιρῷ</span> (Num 9:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:6</a>. <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">αὐτῶν</span> o tempo fixado para o cumprimento das palavras de Gabriel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>; cf. Dg 11:5 (veja  <span class=\"greek\">διαγγέλλω</span> 2). <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">μου</span> meu tempo, isto é, o tempo da minha morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:18</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ ἰαθῆναι</span> tempo de ser curado 2 Cl 9:7. <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ ἄρξασθαι τὸ κρίμα</span>, «tempo de começar o julgamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:17</a>; cf. a construção extraordinária <span class=\"greek\">ἦλθεν ὁ κ</span>. <span class=\"greek\">τῶν νεκρῶν κριθῆναι καὶ δοῦναι</span> = <span class=\"greek\">ἵνα κριθῶσιν οἱ νεκροὶ καὶ δῷς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>.—No plural (Num 9:3 <span class=\"greek\">κατὰ καιρούς</span>; Tob 14:4 S <span class=\"greek\">πάντα συμβήσεται τοῖς καιροῖς αὐτῶν</span>; Heraclit. Sto. 11 p. 18, 18=os intervalos de tempo entre; Maximus Tyr. 1, 2f <span class=\"greek\">πολλοὶ κ</span>.; TestNapht 7:1 <span class=\"greek\">δεῖ ταῦτα πληρωθῆναι κατὰ τοὺς καιροὺς αὐτῶν</span>; Ar. 4, 2 <span class=\"greek\">κατὰ καιρούς</span>) <span class=\"greek\">καιροὶ ἐθνῶν</span> tempos dos gentios (durante os quais podem causar dano ao povo de Deus ou, eles mesmos, converter-se) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:24</a>.—<span class=\"greek\">κατὰ καιρόν</span> no tempo apropriado (Arrian, Anab. 4, 5, 1; PSI 433, 4 [261 b.c.]; Just., A I, 19, 4; Mel., HE 4, 26, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a>; 1 Cl 56:15 (Job 5:26). Também <span class=\"greek\">ἐν καιρῷ</span> (Himerius, Or 13 [Ecl. 14], 3): <span class=\"greek\">ἐν καιρῷ αὐτοῦ</span> B 11:6, 8 (Ps 1:3). <span class=\"greek\">καιρῷ ἰδίῳ</span> no devido tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:9</a>. No plural, <span class=\"greek\">καιροῖς ἰδίοις</span> no tempo certo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:6</a>; 6:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>; cf. 1 Cl 20:4 (Just., D. 131, 4 <span class=\"greek\">πρὸ τῶν ἰδίων κ</span>.).—<span class=\"greek\">κατὰ τὸν ἴδιον καιρόν</span> versículo 10.—<span class=\"greek\">πεπλήρωται ὁ κ</span>. cumpriu-se o tempo (determinado por Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:15</a>. No plural (cf. Ps 103:19) <span class=\"greek\">ὁρίσας προστεταγμένους καιρούς</span> ele (Deus) determinou tempos estabelecidos (MDibelius, SBHeidAk ’38/39, 2ª parte, p. 6s., «estações»; cf. 1QM 10, 12–15; FMussner, Einige Parallelen [Qumran e discurso do Areópago], BZ 1, ’57, 125–30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>; cf. <span class=\"greek\">κατὰ καιροὺς τεταγμένους</span> 1 Cl 40:1; <span class=\"greek\">ὡρισμένοις καιροῖς καὶ ὥραις</span> versículo 2; <span class=\"greek\">τοῖς προστεταγμένοις κ</span>. versículo 4.\n ③ um período caracterizado por algum aspecto de crise especial, tempo\n ⓐ em sentido geral: o tempo presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a>; 12:11 variante de leitura <span class=\"greek\">ὁ καιρός</span> (isto é, a crise que envolve os cristãos) <span class=\"greek\">ἀπαιτεῖ σε</span> os tempos exigem algo de ti IPol 2:3 (Diod S 17, 27, 2 <span class=\"greek\">ὑπὸ τῶν καιρῶν προεκλήθησαν</span>=foram convocados pelas [circunstâncias críticas dos] tempos). Também <span class=\"greek\">ὁ νῦν κ</span>. (PSI 402, 7 [III b.c.] <span class=\"greek\">ἐν τῷ νῦν καιρῷ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:26</a>; 8:18; 11:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:14</a>; B 4:1. <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ νῦν τῆς ἀνομίας</span> o presente tempo de impiedade 18:2 (veja também b abaixo). <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">ὁ ἐνεστηκώς</span> (Polyb. 1, 60, 9; Jos., Ant. 16, 162) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:9</a>; <span class=\"greek\">ἐν ἐκείνῳ τῷ κ</span>. naquele tempo; então (Gen 21:22; Is 38:1; <span class=\"greek\">τῷ κ</span>. <span class=\"greek\">ἐκείνῳ</span> TestSol D 8, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>; 12:1; 14:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:12</a>. Também <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκεῖνον τὸν κ</span>. (Jos., Ant. 1, 171, Vi. 49; GJs 10:2.—Diod S 2, 27, 1 e Vi. Aesopi G 81 P. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκείνους τοὺς καιρούς</span>=naquele tempo. Cf. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκεῖνο καιροῦ</span> Hippol., Ref. 9, 12, 10.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:1</a>; 19:23. <span class=\"greek\">ἔτι κατὰ καιρὸν ὑπὲρ ἀσεβῶν</span> por aqueles que naquele tempo ainda eram ímpios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:6</a>, embora <span class=\"greek\">κατὰ κ</span>. aqui provavelmente signifique «no tempo certo», como na acepção 1b acima (veja B-D-F §255, 3). <span class=\"greek\">τῷ τότε τῆς ἀδικίας καιρῷ</span> … <span class=\"greek\">τὸν νῦν τῆς δικαιοσύνης</span> Dg 9:1; cf. 9:2. Com referência ao futuro <span class=\"greek\">κατὰ τ</span>. <span class=\"greek\">καιρὸν τοῦτον</span> «nesta época» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:9</a> (Gen 18:10, 14). Cf. EpilMosq 2, citado na acepção 2 acima. <span class=\"greek\">ἐν αὐτῷ τῷ κ</span>. precisamente naquele momento (2 Esdr 5:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:1</a>. Com atração do pronome relativo <span class=\"greek\">ἐν ᾧ κ</span>. naquele tempo; então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:20</a>. <span class=\"greek\">κατὰ τὸν καιρὸν ὸ̔ν καὶ πέρυσι</span> na mesma época do ano anterior Hv 2, 1, 1.\n ⓑ Um dos termos principais relativos ao fim dos tempos: <span class=\"greek\">ὁ καιρός</span> o tempo de crise, os últimos tempos (FBusch, Z. Verständnis d. synopt. Eschatol. Mk 13 neu untersucht ’38; GDelling, D. Zeitverständn. des NTs ’40; WMichaelis, D. Herr verzieht nicht d. Verheissung ’42; WKümmel, Verheissung. u. Erfüllung ’45,3 ’56; OCullmann, Christus u. d. Zeit ’46 [tr. FFilson, Christ and Time ’50, 39–45; 79; 121]) <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">ἤγγικεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>. <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">ἐγγύς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:3</a>; 22:10. <span class=\"greek\">οὐκ οἴδατε πότε ὁ καιρός ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:33</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a> (veja a acepção 3a acima) caso deva ser interpretado escatologicamente (cf. Plut., Mor. 549f). <span class=\"greek\">πρὸ καιροῦ</span> antes do tempo do fim e do juízo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>. <span class=\"greek\">ἐν καιρῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:6</a>. Também <span class=\"greek\">ἐν καιρῷ ἐσχάτῳ</span> 1:5; D 16:2. Pl. <span class=\"greek\">πλήρωμα τῶν καιρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a>. <span class=\"greek\">ἐπηρώτων</span> … <span class=\"greek\">περὶ τῶν καιρῶν</span>, <span class=\"greek\">εἰ ἤδη συντέλειά ἐστιν</span> Hv 3, 8, 9. <span class=\"greek\">τὰ σημεῖα τ</span>. <span class=\"greek\">καιρῶν</span>, «os sinais dos tempos (messiânicos)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:3</a>. <span class=\"greek\">τοὺς καιροὺς καταμάνθανε</span> aprender a compreender os tempos IPol 3:2 (veja WBauer, Hdb. Suppl., volume, nota ao trecho) Os tempos messiânicos são descritos como <span class=\"greek\">καιροὶ ἀναψύξεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:20</a>.—<span class=\"greek\">ἔσχατοι καιροί</span> (ou <span class=\"greek\">ὕστεροι καιροί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1</a>) precedem o <span class=\"greek\">ἔσχατος κ</span>. IEph 11:1 (cf. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐσχάτων κ</span>. AcPl Ha 8, 26 [a restauração é certa=Ox 1601, 40//BMM recto 34]); <span class=\"greek\">χρόνοι ἢ καιροί</span> tempos e épocas (cf. Iren. 1, 17, 2 [Harv. I 168, 9] e <span class=\"greek\">καιρῶν κατὰ χρόνους ἀλλαγή</span> Theoph. Ant. 1, 6 [p. 70, 1]; Artem. 4, 2 p. 203, 25f o <span class=\"greek\">χρόνος</span> divide-se em <span class=\"greek\">καιροὶ καὶ ὧραι</span>), que devem completar-se antes da consumação final <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:7</a> (Estratão de Lâmpsaco, em FWehrli, Die Schule des Aristoteles, V Fgm. 10, 32f <span class=\"greek\">κατὰ τοὺς καιροὺς καὶ τοὺς χρόνους</span>; citado por JBarr, Biblical Words for Time, ’62, 33; veja também Diog. L. 5, 64); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:1</a>. <span class=\"greek\">συντέμνειν τοὺς καιρούς</span> abreviar os (últimos) tempos B 4:3. Semelhantemente, no singular, <span class=\"greek\">ὁ καιρὸς συνεσταλμένος ἐστίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>.—A expressão <span class=\"greek\">καιρὸν καὶ καιροὺς κ</span>. <span class=\"greek\">ἥμισυ καιροῦ</span> também pertence ao vocabulário escatológico; designa o tempo apocalíptico de 1 + 2 + ½ = 3½ anos, durante os quais, segundo Da 12:7 (cf. 7:25) um inimigo tirânico de Deus e de seu povo há de reinar na terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:14</a> (sob a imagem de um monstro serpentiforme, <span class=\"greek\">δράκων</span>)—<span class=\"greek\">ὁ κ</span>. <span class=\"greek\">οὗτος</span> a era presente (cf. <span class=\"greek\">αἰών</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:56</a>; 18:30. Também <span class=\"greek\">ὁ νῦν κ</span>. B 4:1. Enquanto dominado pelo diabo: <span class=\"greek\">ὁ ἄνομος κ</span>. 4:9. <span class=\"greek\">καταργεῖν τὸν κ</span>. <span class=\"greek\">τοῦ ἀνόμου</span> destruir a era do iníquo 15:5. A alma procura <span class=\"greek\">και</span>[<span class=\"greek\">ρο</span>]<span class=\"greek\">ῦ χρόνου αἰ̣ῶ̣νος ἀνάπαυσιν ἐ̣</span>[<span class=\"greek\">ν</span>] <span class=\"greek\">σιγῇ</span> paz no silêncio, no tempo da crise do éon GMary 463, 1.—Sobre Dg 12:9, veja as edições de vGebh.-Harnack e Bihlmeyer.—JMánek, NTS 6, ’59, 45–51; JBarr, Biblical Words for Time, ’62.—B. 954. Schmidt, Syn. II 54–72. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καῖσαρ, αρος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino; título imperial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(=latim Caesar; quanto à distribuição desta palavra, frequente na literatura, inscrições e papiros, veja Hahn [fontes e bibliografia 123, 3] e Magie.—Philo, Joseph., Ar. [ins], Just., SibOr, empréstimo na literatura rabínica—Na literatura aqui examinada, ocorre com artigo apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:21</a> variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:25</a> variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:12</a> [veja B-D-F §254, 1]; Just., A I, 17, 1) imperador, César (originalmente nome próprio, depois empregado como título) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:17</a>, 21a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a>, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:22</a>, 24; 23:2 (veja <span class=\"greek\">φόρος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:12b</a> (cf. Philo, In Flacc. 40), 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:7</a>; 25:8, 10–12, 21; 26:32; 27:24; 28:19; <span class=\"greek\">κύριος Κ</span>. MPol 8:2. <span class=\"greek\">ὀμνύναι τὴν Καίσαρος τύχην</span> (veja <span class=\"greek\">τύχη</span>) 9:2; 10:1. <span class=\"greek\">τὰ Καίσαρος</span> aquilo que pertence ao imperador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:25</a> (HWindisch, Imperium u. Evangelium im NT ’31; KPieper ThGl 25, ’33, 661–69; EStauffer, Gott u. Kaiser im NT ’35; GKittel, Christus u. Imperator ’39; JBenum, Gud och Kejsaren ’40; HLoewe, ‘Render Unto Caesar’ ’40; NHommes, God en Kejzer in het NT ’41; OEck, Urgem. u. Imperium ’41; MDibelius, Rom u. die Christen im 1. Jahrh. ’42; JDerrett, Law in the NT, ’70). <span class=\"greek\">φίλος τ</span>. <span class=\"greek\">Καίσαρος</span> amigo do imperador (como título oficial CIG 3499, 4; 3500, 4; Epict. 3, 4, 2; 4, 1, 8; 45–48; 95; 4, 4, 5; Jos., Ant. 14, 131) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:12a</a> (EBamel, TLZ 77, ’52, 205–10); AcPl Ha 11, 4. <span class=\"greek\">οἱ ἐκ τῆς Καίσαρος οἰκίας</span> aqueles (escravos) que pertencem à casa imperial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:22</a> (veja Lghtf., Phil 171ff; Dssm., LO 127, 1; 202, 3; 380 [LAE 382]; New Docs 3, 7–9; e veja <span class=\"greek\">οἰκία</span> 3).—Com nomes próprios <span class=\"greek\">Τιβέριος Κ</span>. imperador Tibério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a> (Just., A I, 13, 3). <span class=\"greek\">ἐπὶ Κλαυδίου Κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a> variante de leitura (cf. Just., A I, 26, 2; 56, 2). <span class=\"greek\">Κ</span>. <span class=\"greek\">Νέρων</span>, na subscrição de 2 Ti; sem nome AcPl Ha 9, 4; 14; 26. Mas <span class=\"greek\">Καῖσαρ Αὔγουστος</span>, César Augusto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:1</a>, pois aqui <span class=\"greek\">Κ</span>. não é um título, mas parte do nome (Bl-D. §5, 3a).—Pauly-W. Suppl. IV 806–53; IX 1139–54; Kl. Pauly II 1110–122; IV 1135–40. B. 1324. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καισάρεια, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(<span class=\"greek\">Καισαρία</span>, acentuação incorreta; veja W-S. §5, 13c, final) Cesareia.\n ① <span class=\"greek\">Καισάρεια ἡ Φιλίππου</span> Cesareia de Filipe, cidade ao pé do monte Hermom, outrora conhecida como Paneias, reconstruída por Filipe, o tetrarca, e transformada numa cidade importante; recebeu dele o nome Cesareia em homenagem a Tibério César (Jos., Ant. 18, 28, Bell. 2, 168) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:13</a>. <span class=\"greek\">αἱ κῶμαι Κ</span>. <span class=\"greek\">τῆς Φ</span>. são aldeias próximas da cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:27</a>.—Schürer II 169–71 (fontes e bibliografia); Dalman, Orte3 (índice).\n ② <span class=\"greek\">Καισάρεια</span> sem outra especificação designa Cesareia «Marítima» (Philo, Leg. ad Gai. 305; Jos., Bell. 7, 23 [here both Caesareas together]), situada ao sul do monte Carmelo, fundada por Herodes, o Grande, no local da antiga Torre de Estratão; recebeu o nome Cesareia em homenagem a Augusto César e mais tarde tornou-se sede dos procuradores romanos (Jos., Ant. 13, 313; 15, 293; 331ff; 19, 343, Bell. 1, 408–14, veja  index). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:40</a>; 9:30; 10:1, 24; 11:11; 12:19; 18:22; 21:8, 16; 23:23, 33; 25:1, 4, 6, 13.—Schürer II 115–18 (fontes e bibliografia); LHaefeli, Caesarea am Meere 1923; CKopp, The Holy Places of the Gospels, tradução de RWalls, ’63, 231–35; ANeger, Encyclopedia of Archaeological Excavations in the Holy Land I, ’75, 270–85; BHHW I 295f; Kl. Pauly III 48f; OEANE I 399–404.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καίτοι, καίτοιγε</h1><div class=\"entry-meta\"><span>conjunção; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">καί</span> 2i<span class=\"greek\">δ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(atestada desde Homero) futuro <span class=\"greek\">καύσω</span> LXX; 1º aoristo <span class=\"greek\">ἔκαυσα</span>. Na voz passiva: infinitivo do 1º aoristo <span class=\"greek\">καυθῆναι</span> (MPol 5:2 variante de leitura) e 2º aoristo (B-D-F §76, 1; Rob. 349f) <span class=\"greek\">καῆναι</span> (MPol 5:2; 12:3); futuro <span class=\"greek\">καυθήσομαι</span> (<span class=\"greek\">καυθήσωμαι</span>, variante de leitura em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a>, forma impossível, veja W-S. §13, 7; B-D-F §28; Mlt-H. 219) e <span class=\"greek\">καήσομαι</span> (Hs 4, 4); particípio perfeito <span class=\"greek\">κεκαυμένος</span>.\n ① fazer acender ou manter em chamas; acender; conservar aceso\n ⓐ literalmente, <span class=\"greek\">λύχνον</span>, uma lâmpada (Posidon: 87 Fgm. 94 Jac.; cf. Lev 24:2, 4; Jos., C. Ap. 1, 308; PGM 4, 2372) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a> (assim, na voz ativa, <span class=\"greek\">καίω τι</span> X., An. 4, 4, 12; 4, 1, 11; EpJer 18. Entretanto, em contraste com <span class=\"greek\">ἅπτω</span>, <span class=\"greek\">κ</span>. enfatiza menos o ato de acender e mais a manutenção da chama; veja Jülicher, Gleichn. 80.—Diod S 13, 111, 2 <span class=\"greek\">πυρὰ κάειν</span>=manter os fogos acesos). Na voz passiva: com sentido ativo, «estar aceso», «arder» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a> variante de leitura <span class=\"greek\">λύχνοι καιόμενοι</span> (Artem. 2, 9; cf. Phlegon: 257 Fgm. 36. 1, 1 Jac. <span class=\"greek\">καιομένου τοῦ λύχνου</span>; Ex 27:20; Jos., Ant. 8, 90) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:35</a>; <span class=\"greek\">λαμπάδες</span> … <span class=\"greek\">καιόμεναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:5</a>; GJs 7:2; cf. <span class=\"greek\">ἀστὴρ</span> … <span class=\"greek\">καιόμενος ὡς λαμπάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:10</a>. <span class=\"greek\">πῦρ καιόμενον</span> (Hdt. 1, 86; Is 4:5; SibOr 7, 6) MPol 11:2a. <span class=\"greek\">κλίβανος καιόμενος</span> forno ardente ou aquecido (Hos 7:4) 2 Cl 16:3. Com acréscimo de <span class=\"greek\">πυρί</span> (Pla., Phd. 113a <span class=\"greek\">εἰς τόπον μέγαν πυρὶ πολλῷ καιόμενον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a> (cf. Dt 4:11; 5:23; 9:15); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:8</a>. <span class=\"greek\">πυρὶ καὶ θείῳ</span> com fogo e enxofre (cf. Is 30:33) 21:8; cf. 19:20.\n ⓑ figuradamente, a respeito de experiências emocionais (escólio a Apollon. Rhod. 3, 762 <span class=\"greek\">ἡ ὀδύνη καίουσα</span>; Philo, Decal. 49 <span class=\"greek\">καιόμενοι κ</span>. <span class=\"greek\">κατακαιόμενοι ὑπὸ τ</span>. <span class=\"greek\">ἐπιθυμιῶν</span>) a respeito do coração <span class=\"greek\">οὐχὶ ἡ καρδία ἡμῶν καιομένη ἦν</span>; não ardia o nosso coração? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:32</a> (cf. PGM 7, 472 <span class=\"greek\">καιομένην τὴν ψυχὴν κ</span>. <span class=\"greek\">τὴν καρδίαν</span>; TestNapht 7:4 <span class=\"greek\">ἐκαιόμην τοῖς σπλάγχνοις</span>. PGrenf I, 1 I, 9 [II b.c.] <span class=\"greek\">συνοδηγὸν ἔχω τὸ πολὺ πῦρ τὸ ἐν τῇ ψυχῇ μου καιόμενον</span>. Cf. Ps 38:4. Sobre as variantes, veja, além dos comentários, WAllen, JTS 2, 1901, 299).\n ② fazer algo arder até ser consumido; queimar inteiramente ativo transitivo (Hom. et e outros; Job 15:34; Just., A I, 53f) MPol 18:1. Na voz passiva: intransitivo, «ser queimado» (Is 5:24; Jos., Ant. 4, 248 [<span class=\"greek\">ἡ παιδίσκη</span>] <span class=\"greek\">καιέσθω ζῶσα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:40</a> variante de leitura (em lugar de <span class=\"greek\">κατακαίεται</span>, veja  <span class=\"greek\">κατακαίω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:6</a>; Hs 4:4. As pedras que são queimadas Hv 3, 2, 9; 3, 7, 2 devem ser entendidas como representações dos apóstatas: ApcPt Bodl. (reconstituído por Bartlet).—MPol 12:3a. <span class=\"greek\">σὰρξ καιομένη</span> 15:2. <span class=\"greek\">δεῖ με ζῶντα καυθῆναι</span> devo ser queimado vivo 5:2; cf. 12:3b (Ael. Aristid, 36, 67 K.=48 p. 465 D.: <span class=\"greek\">καυθήσεσθαι ζῶντες</span>; 45 p. 74 D.; Appian, Hann. 31 §132 <span class=\"greek\">ζῶντας ἔκαυσε</span>). O sentido é discutido em <span class=\"greek\">ἐὰν παραδῶ τὸ σῶμά μου ἵνα καυθήσομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a> variante de leitura (em lugar de <span class=\"greek\">καυχήσωμαι</span>; veja <span class=\"greek\">καυχάομαι</span> 1). A maioria dos estudiosos entende a passagem como referência ao martírio (por exemplo, Ltzm., JSickenberger, H-D Wendland.—Cf. e.g. Da 3:19f; 2 Macc 7:5; 4 Macc 6:26; 7:12; Jos., Ant. 17, 167. Também Dio Chrys. 7 [8], 16 <span class=\"greek\">μαστιγούμενον κ</span>. <span class=\"greek\">τεμνόμενον κ</span>. <span class=\"greek\">καόμενον</span>).—JWeiss (em Meyer9) e FDölger (Antike u. Christentum I 1929, 254–70) preferem interpretá-la como autoimolação voluntária pelo fogo (Diod S 17, 107, 1–6 <span class=\"greek\">Κάλανος</span>; Lucian, Peregr. 20 <span class=\"greek\">καύσων ἑαυτόν</span>, acerca de Peregrino; RFick, D. ind. Weise Kalanos u. veja  Flammentod: NGG, Phil.-Hist. Kl. ’38; NMacnicol, ET 55, ’43/44, 50–52). KSchmidt (TW III 466–69) deixa em aberto a escolha entre as duas possibilidades mencionadas.—Preuschen (ZNW 16, 1915, 127–38) interpreta-a como «marcar a ferro», «marcar como escravo», isto é, vender-se como escravo e entregar o preço da venda à caridade (para essa concepção, veja 1 Cl 55:2).—B. 75. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀκεῖ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio (formado por crase [sobre crase no NT, veja HvSoden, D. Schriften d. NT I/2, 1911, 1380f] de <span class=\"greek\">καὶ ἐκεῖ</span>; apresentado de diversas maneiras nos manuscritos). Encontrado em Eratosth. p. 22, 11; 31, 10; Diod S 4, 34, 1; 4, 85, 5; inscrição ática do século I a.C. [Meisterhans3-Schw.]; 3 Macc 7:19; em outras passagens da LXX, em manuscritos particulares [Thackeray 138]; En 10:4 e outros; TestSol 8:5 P; GrBar; Jos., Ant. 16, 299; Just., D. 56, 6 e outros; Mel. Fgm. 8b [2], 15).\n ① marcador de acréscimo de lugar: «e ali» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:23</a>; 10:11; 28:10 (variante de leitura <span class=\"greek\">καὶ ἐκεῖ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:35</a>; 14:15 variante de leitura (em lugar de <span class=\"greek\">καὶ ἐκεῖ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.54\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:7</a>; 22:10; 25:20; 27:6; ApcPt 18:33. <span class=\"greek\">ὧδε κἀκεῖ</span> Hm 5, 2, 7; Hs 9, 3, 1 (<span class=\"greek\">κἀκεῖσε</span> cod. A em ambos os casos).\n ② marcador de localização que enfatiza a conexão com o relato precedente: «também ali» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:38</a> variante de leitura (em lugar de <span class=\"greek\">καὶ ἐκεῖ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:13</a>. <span class=\"greek\">κἀκεῖ δέ</span> mas também ali 1 Cl 41:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀκεῖθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio (formado por crase de <span class=\"greek\">καὶ ἐκεῖθεν</span>. Inscrição ateniense em SIG 640, 8 [175/174 b.c.]; não ocorre na LXX [Thackeray 138]).\n ① indica procedência de um lugar afastado do falante: «e dali», «e desde lá» (En 21:7 e outros; JosAs 24:21 cod. A; Lucian, Dial. Deor. 7, 4; Jos., Ant. 14, 379) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:4</a>; 14:26; 16:12; 20:15; 21:1; 27:4; 28:15; MPol 7:1.\n ② um momento posterior a outro: «e então», «depois disso» (<span class=\"greek\">ἐκεῖθεν</span> nessa acepção em Diod, S. e Cássio Dio) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:21</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀκεῖνος, η, ο</h1><div class=\"entry-meta\"><span>pronome contraído</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(formado por crase de <span class=\"greek\">καὶ ἐκεῖνος</span>; apresentado de diversas maneiras nos manuscritos; X., Cyr. 5, 5, 29 codd.; Diod S 3, 17, 5; 4, 84, 4; 11, 56, 8; PParis 2 col. 15 [antes de 165 a.C.]; Wsd 18:1; Is 57:6; 2 Macc 1:15 [veja  Thackeray 138]; TestSol 9:7 P; TestReub 6:2; Just.; Ath., R. 19, p. 72, 6).\n ① diz respeito a algo relativamente distante, na especificação de personagens ou elementos narrativos: «e aquele» (indivíduo ou objeto)\n ⓐ e aquele; e ele ou ela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔσωθεν</span> o outro, a saber, aquele que está dentro; 22:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:2</a>. Após <span class=\"greek\">ταῦτα</span>: «este … e aquele», «um … e outro» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:23</a> (par. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:42</a>).\n ⓑ aquele também; também ele ou ela (Lucian, Dial. Deor. 2, 2; 7, 3; Just., D. 17, 1; 122, 1; 123, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:16</a>; 17:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:37</a>; 15:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:2</a>. <span class=\"greek\">κἀκεῖνοι δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:23</a>.\n ② diz respeito à especificação de uma entidade, com valor intensificador em referência ao que se destaca\n ⓐ e ele; e isso (aquilo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:18</a> <span class=\"greek\">κἀκεῖνα κοινοῖ</span> e são essas coisas que contaminam; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:11</a> <span class=\"greek\">κἀκεῖνοι ἀκούσαντες</span> eles, por sua vez, ao ouvirem; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:57</a> <span class=\"greek\">καὶ ὁ τρώγων με κἀκεῖνος ζήσει</span> assim também aquele que de mim se alimenta viverá; 7:29 <span class=\"greek\">κἀκεῖνος με ἀπέστειλεν</span> e esse é aquele que me enviou (semelhantemente 14:12); 19:35 variante de leitura (em lugar de <span class=\"greek\">καὶ ἐ</span>.); semelhantemente\n ⓑ este, aquele (Jos., Ant. 14, 474) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:4f</a> (par. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:11</a>); 16:13.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀκεῖσε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio (formado por crase de <span class=\"greek\">καὶ ἐκεῖσε</span>; Appian, Iber. 26 §103; Herodian 4, 8, 6; Jos., Ant. 7, 327) e lá; e para lá, sempre acompanhado de <span class=\"greek\">ὧδε</span> (Aesop 62) a leitura do códice A em lugar de <span class=\"greek\">καὶ ἐκεῖ</span> Hs 6, 1, 6; 6, 2, 7; em lugar de <span class=\"greek\">κἀκεῖ</span> m 5, 2, 7; Hs 9, 3, 1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">κακός</span>; Theognis, Pre-Socr.+)\n ① qualidade ou estado de perversidade, vileza, depravação, maldade, vício. <span class=\"greek\">κ</span>. é o oposto de <span class=\"greek\">ἀρετή</span> e de toda virtude, carecendo, portanto, de valor social (X., Mem. 1, 2, 28; Aristot., Rhet. 2, 6; EN 2, 3–7; Cicero, Tusc. 4, 15; Appian, Bell. Civ. 4, 129 §544 <span class=\"greek\">κακία</span>-<span class=\"greek\">ἀρετή</span>; Just., A I, 28, 4 e Ath. 24, 4; R. 22 p. 75, 11; Herm. Wr. 9, 4b; SIG 1268, 18 <span class=\"greek\">κακίας ἀπέχου</span>; Sb 4127, 6; Wsd 7:30; 12:2, 10; Sir 14:6, 7 e outros; LXX; oft. Philo; Jos., Ant. 8, 252; Orig., C. Cels. 2, 76, 82; Did., Gen. 39, 24) 2 Cl 10:1. <span class=\"greek\">περισσεία κακίας</span> excesso de maldade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21</a>. <span class=\"greek\">δεσμὸς κακίας</span> laço de maldade IEph 19:3. Com <span class=\"greek\">πονηρία</span> no mesmo sentido geral (cf. Ael. Aristid. 33 p. 625 D.; Sir 25:17, 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:8</a>. <span class=\"greek\">πάσης κ</span>. <span class=\"greek\">πλήρης</span> 1 Cl 45:7. <span class=\"greek\">τῇ κακίᾳ νηπιάζειν</span> ser criança quanto à maldade, isto é, possuir tão pouca experiência do mal quanto uma criança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:20</a>; cf. Hs 9, 29, 1; 3. <span class=\"greek\">μετανόησον ἀπὸ τ</span>. <span class=\"greek\">κακίας σου ταύτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:22</a> (Just., D. 109, 1). <span class=\"greek\">ὡς ἐπικάλυμμα ἔχοντες τ</span>. <span class=\"greek\">κακίας τὴν ἐλευθερίαν</span> usar a liberdade como cobertura para a maldade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:16</a> (cf. <span class=\"greek\">ἵνα μὴ εἰς ἐπικάλλυμα κακίας καταχρησώμεθα τῇ ἐλευθερίᾳ</span> Iren. 4, 37, 4 [Harv. II 288, 11]; veja  <span class=\"greek\">ἐπικάλλυμα</span>).\n ② atitude ou disposição mesquinha ou viciosa: malícia, má vontade, malignidade (Diod S 1, 1; PRein 7, 15 [II b.c.]; POxy 1101, 7; Philo; Just., D. 65, 2 <span class=\"greek\">ἁπλῶς καὶ μὴ μετὰ κακίας εἰπών</span>; 136, 2; Tat. 34, 1) junto de outros vícios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:1</a>; B 20:1; D 5:1. <span class=\"greek\">τὸ στόμα σου ἐπλεόνασεν κακίαν</span> 1 Cl 35:8 (Ps 49:19). Cf. B 2:8 (Zech 8:17).\n ③ estado caracterizado por circunstâncias difíceis: aflição, adversidade, infortúnio (Thu. 3, 58, 1 opp. <span class=\"greek\">ἡδονή</span>; 1 Km 6:9; Eccl 7:14 <span class=\"greek\">ἐν ἡμέρᾳ κακίας</span>; 12:1; Sir 19:6; Am 3:6; 1 Macc 7:23; Jos., Ant. 1, 97; Just., D. 142, 3) <span class=\"greek\">ἀρκετὸν τῇ ἡμέρᾳ ἡ κ</span>. <span class=\"greek\">αὐτῆς</span> a cada dia basta o seu próprio mal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:34</a>—GBaumbach, Das Verständnis des Bösen in den synopt. Evv., ’63.—DELG sob o verbete <span class=\"greek\">κακός</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοδιδασκαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Sexto Empírico, Adv. Math. 2, 42; veja <span class=\"greek\">κακοδιδασκαλία</span> e <span class=\"greek\">καλοδιδάσκαλος</span>) ensinar o mal a alguém (<span class=\"greek\">τινά</span>); <span class=\"greek\">τὰς ἀναιτίους ψυχάς</span>, «às almas inocentes» 2 Cl 10:5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοδιδασκαλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ensino mau ou ftambém IPhld 2:1 (=<span class=\"greek\">κακὴ διδασκαλία</span> IEph 16:2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοήθεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">κακός</span>, <span class=\"greek\">ἦθος</span>; X., Pla. et e outros; T. Kellis 22, 22) defeito fundamental do caráter que leva alguém a prejudicar os outros: mesquinhez, malícia, malignidade, astúcia (assim Políbio 5, 50, 5; Vett. Val. 44, 20; PGrenf I, 60, 13 [cf. Sb 5112, 15]; Esth 8:12f; 3 Macc 3:22; Jos., Ant. 1, 50; 16, 68, C. Ap. 1, 222 [com <span class=\"greek\">φθόνος</span>]; Tat. 16, 1) em um catálogo de vícios (Apolônio de Tiana, Ep. 43 [Philostrat. I 354, 6]: <span class=\"greek\">φθόνου</span>, <span class=\"greek\">κακοηθείας</span>, <span class=\"greek\">μίσους</span>, <span class=\"greek\">διαβολῆς</span>, <span class=\"greek\">ἔχθρας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a>; 1 Cl 35:5 (Aristóteles, Rhet. 2, 13, p. 1389b, 20s., define o termo assim: <span class=\"greek\">ἔστι κακοήθεια τὸ ἐπὶ τὸ χεῖρον ὑπολαμβάνειν ἅπαντα</span>=malícia significa presumir o pior em todas as coisas; Ammonius [100 a.d.] p. 80 Valck. define-o como <span class=\"greek\">κακία κεκρυμμένη</span>=vileza escondida nas sombras. Cf. 4 Macc 1:4; 3:4).—DELG sob o verbete <span class=\"greek\">ἦθος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοήθης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo precedente; Pla., Menand. et e outros; Vett. Val. 47, 2; 4; PGiss 40 II, 11; 4 Macc 1:25; 2:16; Philo, Somn. 2, 192; Jos., Ant. 1, 42; contraste com <span class=\"greek\">καλοήθης</span> numa lista de virtudes: Cat. Cod. Astr. XII 100, 9) malicioso, rancoroso D 2:6.—M-M. sob o verbete <span class=\"greek\">κακοήθεια</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακολάλος</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">κατάλαλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακολογέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito, 3ª pessoa do singular <span class=\"greek\">ἐκακολόγει</span> 2 Macc 4:1; 3ª pessoa do plural <span class=\"greek\">ἐκακολόγουν</span> Ezk 22:7; futuro, 2ª pessoa do singular <span class=\"greek\">οκακολογήσεις</span> Ex 22:27 (<span class=\"greek\">κακολόγος</span> «caluniador»; Lysias 8, 5; Plut., Vett. Val. et e outros; PFay 12, 15 [II b.c.]; PRyl 150, 9; SB V/2, 7835, 15f [I b.c.]; LXX) falar mal de, injuriar, insultar alguém (<span class=\"greek\">τινά</span>) (Jos., Ant. 20, 180) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:39</a>. <span class=\"greek\">πατέρα ἢ μητέρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:10</a> (ambos em Ex 21:16; cf. Pr 20:9a: Ezk 22:7). <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">τὴν ὁδόν</span> o Caminho (isto é, a maneira cristã de viver) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:9</a>. Em uso absoluto: D 2:3.—DELG sob o verbete <span class=\"greek\">λέγω</span> B2b. New Docs 2, 88, com crítica a M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοπάθεια</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">κακοπαθία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοπαθέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo seguinte) 1º aoristo <span class=\"greek\">ἐκακοπάθησα</span>, imperativo <span class=\"greek\">κακοπάθησον</span>.\n ① sofrer infortúnios (X., Mem. 1, 4, 11; Polyb. 3, 72, 5; Teles 61, 6; Musonius 28, 9; Vett. Val. 106, 10; PEdg 14, 17 [=Sb 6720–257/256 b.c.]; PLond I, 98 recto, 73 p. 130 [I/II a.d.]; PRyl 28, 84; Jon 4:10; EpArist 241; Philo, Somn. 2, 181; Jos., Ant. 12, 336, C. Ap. 2, 203) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:13</a>; 2 Cl 19:3. (Sobre Ox 1602, 23s., veja a nota do editor acerca da correção de <span class=\"greek\">καλοπαθοῦντες</span> no papiro; a duplicata AcPl Ha 8, 19 apresenta a leitura [<span class=\"greek\">π</span>]<span class=\"greek\">ο̣λλὰ γ̣ὰρ παθόντες</span>//BMM recto 24.)\n ② suportar pacientemente as dificuldades (Aristot., EN 10, 6, 1176b, 29; Appian, Bell. Civ. 5, 87 §364; Philo, Virt. 88; Jos., Ant. 10, 220) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:5</a>.—DELG sob o verbete <span class=\"greek\">πάσχω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0183-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κακοπαθία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(esta grafia ocorre em inscrições desde o século III a.C.; também em BGU 1209, 7 [23 a.C.]; grafia alternativa nos manuscritos <span class=\"greek\">κακοπάθεια</span> [veja W-S. §5, 13c, p. 44f; B-D-F §23; veja o artigo precedente]) sofrimento. Tanto em sentido passivo, como sofrimento, infortúnio ou desgraça que sobrevêm a uma pessoa (Thu. 7, 77, 1 e outros; Mal 1:13; 2 Macc 2:26f; EpArist 208; Philo, De Jos. 223; Ath., R. 18 p. 71, 10; R. 22, p. 75, 19), quanto em sentido ativo, como sofrimento que alguém suporta, esforço árduo que empreende ou perseverança que exercita (Polyb. 3, 42, 9; 4, 8, 3; Plut., Numa 3, 5; Vett. Val. 277, 16; 4 Macc 9:8; EpArist 92; 259. As inscrições desde OGI 244, 12 [III b.c.], veja a nota do editor. Também o papiro [BGU] mencionado acima; veja  Dssm., NB 91f [BS 263f]; Thieme 29). Esta última acepção aparentemente se tornou preferida em épocas posteriores e, por isso, deve ser adotada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:10</a> (variante de leitura: <span class=\"greek\">καλοκαγαθίας</span>), onde apresenta ainda a vantagem de ajustar-se melhor ao contexto. Diversamente GBjörck, ConNeot 4, ’40, 3, que interpreta <span class=\"greek\">κ</span>. juntamente com <span class=\"greek\">μακροθ</span>. como hendíade.—DELG sob o verbete <span class=\"greek\">κακός</span>, <span class=\"greek\">πάσχω</span> 2. M-M. TW. Spicq.</p></section></article>\n"};
